"""Validate datasets generated by AURELIUS generate_survival.py.
Usage: python validate_survival.py --data ml_data_10000
Requires pandas, numpy; pyarrow for parquet input.
"""
import argparse
from pathlib import Path
import numpy as np
import pandas as pd

FROZEN = ['age_months','industry','entity_type','monthly_revenue','revenue_trend_12m',
          'revenue_volatility','operating_margin','cash_buffer_months','dscr',
          'debt_to_revenue','prior_overdue_30d','requested_amount','term_months',
          'annual_rate','macro_stress','origination_month_index']

def load_parts(folder, pattern):
    paths = sorted(folder.glob(pattern + '_part_*.parquet'))
    if not paths:
        paths = sorted(folder.glob(pattern + '_part_*.csv'))
    if not paths:
        raise FileNotFoundError(f'No {pattern}_part_*.parquet/csv files in {folder}')
    if any(p.suffix != paths[0].suffix for p in paths):
        raise ValueError('Mixed file formats')
    return pd.concat([pd.read_parquet(p) if p.suffix == '.parquet' else pd.read_csv(p)
                      for p in paths], ignore_index=True)

def quantile_table(df, column, labels=5):
    # At episode level, so a long-surviving borrower is not counted multiple times.
    data = df[['episode_id', column, 'event']].dropna()
    try:
        groups = pd.qcut(data[column], q=labels, duplicates='drop')
    except ValueError:
        return pd.DataFrame()
    out = data.groupby(groups, observed=True).agg(
        episodes=('episode_id', 'size'), events=('event', 'sum'),
        avg_value=(column, 'mean'))
    out['event_fraction'] = out['events'] / out['episodes']
    return out.reset_index().astype({column: 'str'})

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--data', type=Path, default=Path('ml_data_10000'))
    parser.add_argument('--output', type=Path, default=None)
    args = parser.parse_args()
    folder = args.data
    dest = args.output or folder / 'validation'
    dest.mkdir(parents=True, exist_ok=True)
    print('Reading datasets...')
    splits = {s: load_parts(folder, s) for s in ('train', 'val', 'test')}
    episodes = load_parts(folder, 'episodes')
    rows = pd.concat([d.assign(split=s) for s, d in splits.items()], ignore_index=True)
    problems = []
    def check(name, ok, detail=''):
        status = 'PASS' if ok else 'FAIL'
        print(f'[{status}] {name}' + (f' — {detail}' if detail else ''))
        if not ok: problems.append(name)

    required = {'episode_id','borrower_id','month_on_book','default_event','origination_month_index'} | set(FROZEN)
    check('Required columns', required.issubset(rows.columns))
    if not required.issubset(rows.columns):
        print('Missing:', sorted(required - set(rows.columns)))
        return
    check('Episode metadata columns', {'episode_id','borrower_id','split','event','event_month','observed_months','term_months','censored'}.issubset(episodes.columns))
    check('No missing required features', not rows[list(required)].isna().any().any())
    check('No duplicate episode/month', not rows.duplicated(['episode_id','month_on_book']).any())
    check('No duplicate episode metadata', not episodes.duplicated('episode_id').any())
    check('One episode per borrower (current generator)', episodes.groupby('borrower_id').episode_id.nunique().max() == 1)
    check('Unique borrower across splits', rows.groupby('borrower_id').split.nunique().max() == 1)
    check('Valid binary event', rows.default_event.isin([0,1]).all())
    check('No more than one default per episode', rows.groupby('episode_id').default_event.sum().max() <= 1)
    check('Chronological split ranges', all((d.origination_month_index.lt(59) if s=='train' else
         d.origination_month_index.between(59,71) if s=='val' else d.origination_month_index.ge(72)).all()
         for s,d in splits.items()))
    check('No observed month beyond contractual term', (rows.month_on_book <= rows.term_months).all())
    check('Month-on-book starts at 1 and is continuous', bool((rows.groupby('episode_id').month_on_book.min()==1).all()
          and (rows.groupby('episode_id').month_on_book.nunique()==rows.groupby('episode_id').month_on_book.max()).all()))
    check('Origination features remain frozen', bool((rows.groupby('episode_id')[FROZEN].nunique(dropna=False).max() <= 1).all()))
    last = rows.groupby('episode_id').agg(observed_from_rows=('month_on_book','max'),
                                        event_from_rows=('default_event','sum'))
    event_month = rows.loc[rows.default_event.eq(1), ['episode_id','month_on_book']].set_index('episode_id').month_on_book
    last['event_month_from_rows'] = event_month
    ep = episodes.set_index('episode_id')
    check('Episode IDs match row IDs', set(ep.index)==set(last.index))
    joint = ep.join(last, how='left')
    check('Episode observation lengths match', (joint.observed_months == joint.observed_from_rows).all())
    check('Episode event flags match', (joint.event == joint.event_from_rows).all())
    check('Event month matches', ((joint.event.eq(0) & joint.event_month.isna()) |
         (joint.event.eq(1) & joint.event_month.eq(joint.event_month_from_rows))).all())
    check('Default occurs on final observed row', (rows.loc[rows.default_event.eq(1)].groupby('episode_id').month_on_book.max()
         == last.loc[last.event_from_rows.eq(1), 'observed_from_rows']).all())
    expected_censored = joint.event.eq(0) & joint.observed_months.lt(joint.term_months)
    check('Censor flags match', joint.censored.eq(expected_censored.astype(int)).all())
    check('No nonfinite numeric features', np.isfinite(rows[FROZEN].select_dtypes(include='number').to_numpy()).all())
    check('DSCR positive', rows.dscr.gt(0).all())
    check('Requested amount positive', rows.requested_amount.gt(0).all())
    check('Observed cohort within generator bounds', rows.origination_month_index.between(0,83).all())

    # Per-episode snapshots; episode event fractions are NOT annual PDs.
    snap = rows.sort_values('month_on_book').drop_duplicates('episode_id').copy()
    snap = snap.merge(episodes[['episode_id','event','observed_months','censored']], on='episode_id', how='left', validate='one_to_one')
    overview = snap.groupby('split').agg(borrowers=('borrower_id','nunique'),
                                        episodes=('episode_id','size'),
                                        defaults=('event','sum'),
                                        avg_observed_months=('observed_months','mean'),
                                        censored=('censored','sum'))
    overview['event_fraction_over_observation'] = overview.defaults/overview.episodes
    overview.to_csv(dest / 'overview.csv')
    print('\nEPISODE OVERVIEW (event fraction is NOT annual PD):')
    print(overview.round(4).to_string())
    for col in ('dscr','debt_to_revenue','cash_buffer_months','revenue_trend_12m',
                'revenue_volatility','prior_overdue_30d','industry'):
        if col in ('industry','prior_overdue_30d'):
            t = snap.groupby(col, observed=True).agg(episodes=('event','size'),events=('event','sum'))
            t['event_fraction'] = t.events/t.episodes
            t.reset_index().to_csv(dest / f'by_{col}.csv',index=False)
        else:
            quantile_table(snap, col).to_csv(dest / f'by_{col}.csv',index=False)
    hazard = rows.groupby('month_on_book').agg(at_risk=('default_event','size'),events=('default_event','sum'))
    hazard['empirical_hazard'] = hazard.events/hazard.at_risk
    hazard.to_csv(dest / 'hazard_by_month.csv')
    # Diagnostic at-risk rate, not a causal effect estimate; cohorts/censoring differ.
    print('\nFIRST 12 MONTHS:')
    print(hazard.head(12).round(5).to_string())
    print('\nDSCR GROUPS (event fraction affected by follow-up duration):')
    print(quantile_table(snap,'dscr').round(4).to_string(index=False))
    print('\nDEBT/REVENUE GROUPS:')
    print(quantile_table(snap,'debt_to_revenue').round(4).to_string(index=False))
    print('\nIMPORTANT: These are descriptive associations, NOT causal effects or annual PDs.')
    print('The generator uses calendar-month macro stress to produce events but freezes origination macro_stress as a model feature.')
    print('This validator cannot prove absence of all leakage or external predictive validity.')
    print(f'\nResults saved in: {dest}')
    print(f'Validation: {len(problems)} failed checks' if problems else 'Validation: all structural checks passed')
    if problems:
        raise SystemExit(1)

if __name__ == '__main__':
    main()
